import React, { useState, useEffect } from 'react';
import './App.css';

// Components
import ShippingMap from './components/ShippingMap';
import StockDetailModal from './components/StockDetailModal';
import AuthModal from './components/AuthModal';
import Portfolio from './components/Portfolio';
import AdvancedChart from './components/AdvancedChart';
import StockCompare from './components/StockCompare';
import OptionsChain from './components/OptionsChain';
import PriceAlerts from './components/PriceAlerts';
import AISignals from './components/AISignals';
import NaturalLanguageSearch from './components/NaturalLanguageSearch';
import AnomalyDetection from './components/AnomalyDetection';

// Context
import { AuthProvider, useAuth } from './context/AuthContext';

// Services
import PriceStreamService from './services/PriceStreamService';

function AppContent() {
  const { user, isAuthenticated, login, register, logout } = useAuth();
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [watchlist, setWatchlist] = useState(['AAPL', 'MSFT', 'GOOGL', 'NVDA', 'META', 'AMZN', 'TSLA', 'JPM']);
  const [selectedStock, setSelectedStock] = useState(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [authMode, setAuthMode] = useState('login');
  const [showPortfolio, setShowPortfolio] = useState(false);
  const [realtimePrices, setRealtimePrices] = useState({});
  const [isConnected, setIsConnected] = useState(false);

  // Initialize real-time price streaming
  useEffect(() => {
    PriceStreamService.connect();
    setIsConnected(true);

    const unsubscribe = PriceStreamService.subscribeAll((data) => {
      setRealtimePrices(prev => ({
        ...prev,
        [data.symbol]: data
      }));
    });

    return () => {
      unsubscribe();
      PriceStreamService.disconnect();
    };
  }, []);

  // Loading simulation
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  const formatPrice = (price) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(price);
  };

  const formatChange = (change) => {
    const isPositive = change >= 0;
    return (
      <span style={{ color: isPositive ? '#22c55e' : '#ef4444' }}>
        {isPositive ? '+' : ''}{change.toFixed(2)}%
      </span>
    );
  };

  if (isLoading) {
    return (
      <div className="loading-screen">
        <div className="loading-spinner"></div>
        <h1>Financial Intelligence Platform</h1>
        <p>Loading real-time data...</p>
      </div>
    );
  }

  return (
    <div className="app">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="logo">
          <div className="logo-icon">FI</div>
          <span>Financial Intel</span>
        </div>

        <nav className="nav-menu">
          {[
            { id: 'dashboard', label: 'Dashboard' },
            { id: 'markets', label: 'Markets' },
            { id: 'stocks', label: 'Stocks' },
            { id: 'macro', label: 'Macro' },
            { id: 'shipping', label: 'Shipping' },
            { id: 'news', label: 'News' },
            { id: 'analytics', label: 'Analytics' },
            { id: 'ai', label: 'AI Insights' },
            { id: 'watchlists', label: 'Watchlists' },
            { id: 'alerts', label: 'Alerts' },
          ].map(item => (
            <button
              key={item.id}
              className={`nav-item ${activeTab === item.id ? 'active' : ''}`}
              onClick={() => setActiveTab(item.id)}
            >
              <span className="nav-label">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="sidebar-footer">
          <div className="market-status">
            <span className="status-dot open"></span>
            <span>Markets Open</span>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="main-content">
        {/* Header */}
        <header className="header">
          <div className="header-left">
            <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
            <span className="header-subtitle">Real-time Market Intelligence</span>
          </div>
          <div className="header-right">
            <div className="search-bar">
              <input type="text" placeholder="Search symbols, news..." />
            </div>
            <button className="header-btn">Settings</button>
            <button className="header-btn">Alerts</button>
            <div className="user-avatar">U</div>
          </div>
        </header>

        {/* Dashboard Content */}
        <div className="content">
          {/* Shipping Map View */}
          {activeTab === 'shipping' ? (
            <div style={{ height: 'calc(100vh - 200px)', minHeight: '600px' }}>
              <ShippingMap />
            </div>
          ) : (
            <>
              {/* Market Overview */}
              <section className="market-overview">
                <div className="market-card indices">
                  <h3>Major Indices</h3>
                  <div className="indices-grid">
                    {[
                      { symbol: 'S&P 500', name: 'S&P 500', price: 4783.45, change: 0.85 },
                      { symbol: 'DJIA', name: 'Dow Jones', price: 37468.61, change: 0.42 },
                      { symbol: 'NASDAQ', name: 'NASDAQ', price: 15055.65, change: 1.23 },
                      { symbol: 'RUT', name: 'Russell 2000', price: 2012.34, change: -0.56 },
                    ].map(index => (
                      <div 
                        key={index.symbol} 
                        className="index-item"
                        onClick={() => setSelectedStock(index.symbol)}
                        style={{ cursor: 'pointer' }}
                      >
                        <span className="index-name">{index.name}</span>
                        <span className="index-price">{formatPrice(index.price)}</span>
                        <span className="index-change">{formatChange(index.change)}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </section>

              {/* Watchlist */}
              <section className="watchlist-section">
                <div className="section-header">
                  <h2>Watchlist</h2>
                  <button className="btn-secondary">Edit</button>
                </div>
                <div className="watchlist-grid">
                  {watchlist.map(symbol => (
                    <div 
                      key={symbol} 
                      className="watchlist-item"
                      onClick={() => setSelectedStock(symbol)}
                      style={{ cursor: 'pointer' }}
                    >
                      <div className="stock-info">
                        <span className="stock-symbol">{symbol}</span>
                        <span className="stock-price">{formatPrice(100 + Math.random() * 400)}</span>
                      </div>
                      <div className="stock-change">
                        {formatChange((Math.random() - 0.5) * 10)}
                      </div>
                      <div className="stock-chart">
                        <svg viewBox="0 0 100 30" className="mini-chart">
                          <path
                            d="M0,15 L10,15 L15,12 L25,18 L35,10 L45,22 L55,8 L65,20 L75,5 L85,15 L100,10"
                            fill="none"
                            stroke={Math.random() > 0.5 ? '#22c55e' : '#ef4444'}
                            strokeWidth="1.5"
                          />
                        </svg>
                      </div>
                    </div>
                  ))}
                </div>
              </section>

              {/* Quick Stats */}
              <section className="quick-stats">
                <div className="stats-grid">
                  <div className="stat-card">
                    <h4>Market Sentiment</h4>
                    <div className="sentiment-meter">
                      <div className="sentiment-bar">
                        <div className="sentiment-fill" style={{ width: '62%' }}></div>
                      </div>
                      <span className="sentiment-label">Bullish (62%)</span>
                    </div>
                  </div>
                  <div className="stat-card">
                    <h4>Top Sectors</h4>
                    <div className="sector-list">
                      {[
                        { name: 'Technology', change: '+1.8%' },
                        { name: 'Energy', change: '+1.2%' },
                        { name: 'Healthcare', change: '+0.8%' },
                      ].map((sector, i) => (
                        <div key={i} className="sector-item">
                          <span>{sector.name}</span>
                          <span className="positive">{sector.change}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="stat-card">
                    <h4>Economic Calendar</h4>
                    <div className="events-list">
                      {[
                        { event: 'FOMC Meeting', date: 'Jan 30-31' },
                        { event: 'GDP Release', date: 'Jan 25' },
                        { event: 'CPI Data', date: 'Feb 15' },
                      ].map((event, i) => (
                        <div key={i} className="event-item">
                          <span>{event.event}</span>
                          <span className="event-date">{event.date}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="stat-card">
                    <h4>AI Insights</h4>
                    <div className="insights-list">
                      <div className="insight-item">
                        <span className="insight-icon">UP</span>
                        <span>Tech sector showing strong momentum</span>
                      </div>
                      <div className="insight-item">
                        <span className="insight-icon">!</span>
                        <span>Monitor Fed commentary closely</span>
                      </div>
                      <div className="insight-item">
                        <span className="insight-icon">NEW</span>
                        <span>Volume spike detected in NVDA</span>
                      </div>
                    </div>
                  </div>
                </div>
              </section>
            </>
          )}
        </div>
      </main>

      {/* Stock Detail Modal */}
      {selectedStock && (
        <StockDetailModal 
          symbol={selectedStock} 
          onClose={() => setSelectedStock(null)} 
        />
      )}
    </div>
  );
}

export default App;
